import{z as d,x as B,o as n,c as p,q as s,j as o,D as e,d as r,s as l,S as i,b as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"控制冒险与分支预测","description":"","frontmatter":{"title":"控制冒险与分支预测","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/control-hazard-predict.md","filePath":"cs/control-hazard-predict.md","lastUpdated":1791063341000}'),A={name:"cs/control-hazard-predict.md"};function C(c,a,m,h,u,P){const E=B("Mermaid");return n(),p("div",null,[a[2]||(a[2]=s('<h1 id="控制冒险与分支预测" tabindex="-1">控制冒险与分支预测 <a class="header-anchor" href="#控制冒险与分支预测" aria-label="Permalink to &quot;控制冒险与分支预测&quot;">​</a></h1><div class="epigraph"><p>下一条该取哪一句，往往要等当前这句算出条件；猜错就得把已经取进来的指令丢掉。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/load-use-stall">上一课</a>用转发保住了 ALU 的 RAW 顺序，load-use 仍可能停一拍。本课不重讲旁路 mux。缺口是：IF 每拍都要一个 PC，而条件分支的方向与目标要到 EX 才齐。取错指令不是数据用错，而是控制流用错。本课只处理控制冒险，并把静态/一位动态预测当作可撤销的猜测。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>beq</code> 在 EX 才知道比较结果和目标地址。若 IF 盲目取 PC+4，分支成功时已经灌进一到两条不该执行的指令。全部停到 EX 再取，CPI 被分支频率打穿。缺口不是再加一条转发，而是<strong>在目标未知时仍要取指，错了再冲刷</strong>。</p><p><a href="/cs/calling-convention-stack">调用约定与栈</a>里的跳转、返回是无条件控制流，目标往往更早可知；条件分支才是五级里的硬缺口。本课不把间接跳转预测表铺开。</p><p><span class="marginnote">直觉类比：分支预测像到岔路口不减速、先猜一边开——猜对零损失，猜错就倒车回岔口重来（冲刷流水线）。CPU 宁可偶尔倒车也不每次都停下想清楚，因为「开错了再退」平均比「每次都停」快得多。</span></p><p><span class="marginnote">延迟槽是早期 RISC 把冒险交给软件的办法。当代核几乎不用程序员可见的延迟槽，而用预测加冲刷。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>最简单：假定分支不成功，继续取顺序指令；EX 发现成功则把 IF/ID 作废，从目标重取。代价是成功分支损失两拍（五级里条件在 EX）。把比较前移到 ID 可以少损失一拍，但关键路径变差。</p><p>预测：用分支 PC 索引一位饱和计数器，或固定「向后成功、向前失败」。预测成功则按预测地址取指；EX 核对，错则冲刷并更新计数器。本课只钉「猜 + 核对 + 冲刷」，不引入两级自适应或竞赛预测器。</p>',11)),(n(),o(i,null,{default:e(()=>[l(E,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IF%5B%22IF%20%E6%8C%89%E9%A2%84%E6%B5%8B%20PC%20%E5%8F%96%E6%8C%87%22%5D%20--%3E%20EX%5B%22EX%20%E6%A0%B8%E5%AF%B9%E6%9D%A1%E4%BB%B6%E4%B8%8E%E7%9B%AE%E6%A0%87%22%5D%0A%20%20EX%20--%3E%7C%22%E7%8C%9C%E5%AF%B9%22%7C%20CONT%5B%22%E6%B5%81%E6%B0%B4%E7%BA%BF%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20EX%20--%3E%7C%22%E7%8C%9C%E9%94%99%22%7C%20FLUSH%5B%22%E5%86%B2%E5%88%B7%20IF%2FID%EF%BC%8C%E9%87%8D%E5%8F%96%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[r("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"冲刷与数据转发不同：转发改的是 mux 数据，冲刷改的是「这些级里的指令当作没发生过」。被冲刷的指令不得写寄存器、不得访存。预测器状态在核对后更新，本身不是 ISA 可见的寄存器。",-1)),a[5]||(a[5]=t("p",null,"控制冒险的 CPI 损失 ≈ 分支频率 × 误预测率 × 损失拍数。后课阿姆达尔会把这项与数据停顿、结构停顿加在一起。本课只交出这项的来源。五级里损失拍数由「条件在哪一级才齐」决定，前移比较能减小它，但那是实现交易，不是新的 ISA。",-1)),(n(),o(i,null,{default:e(()=>[l(E,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20B0%5B%22%E7%8A%B6%E6%80%81%200%3A%20%E9%A2%84%E6%B5%8B%E4%B8%8D%E8%B7%B3%E8%BD%AC%22%5D%20--%3E%7C%22%E5%AE%9E%E9%99%85%E6%B2%A1%E8%B7%B3%3A%20%E7%8C%9C%E5%AF%B9%22%7C%20B0%0A%20%20B0%20--%3E%7C%22%E5%AE%9E%E9%99%85%E8%B7%B3%E4%BA%86%3A%20%E7%8C%9C%E9%94%99%22%7C%20B1%5B%22%E7%8A%B6%E6%80%81%201%3A%20%E9%A2%84%E6%B5%8B%E8%B7%B3%E8%BD%AC%22%5D%0A%20%20B1%20--%3E%7C%22%E5%AE%9E%E9%99%85%E8%B7%B3%E4%BA%86%3A%20%E7%8C%9C%E5%AF%B9%22%7C%20B1%0A%20%20B1%20--%3E%7C%22%E5%AE%9E%E9%99%85%E6%B2%A1%E8%B7%B3%3A%20%E7%8C%9C%E9%94%99%22%7C%20B0%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">数字实例：分支占 20%、一位预测器误预测率 10%、每次猜错损失 2 拍，则每条指令平均多付 0.2 × 0.1 × 2 = 0.04 拍，CPI 从 1 涨到 1.04。把误预测率压到 1%，这项就只剩 0.004——现代预测器烧的是巨额晶体管，买的正是这几个百分点。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理异常：中断和缺页也会让已取指令作废，但精确异常要另订提交点，见<a href="/cs/pipeline-exception">流水线异常</a>。也不把预测器做成可被用户态编程的架构状态。特权级下的陷阱与 <code>eret</code> 仍走上一课已经钉死的入口，只是流水线要冲刷用户指令。</p><p>后课默认：五级核用预测取指，误预测冲刷；正确路径上的 RAW 仍靠转发。</p><p><span class="marginnote">常见误区：以为猜错的指令「执行了一半也无妨」。被冲刷的指令绝不允许写寄存器或访存，否则猜错一次就污染了程序可见的状态——这条红线正是后课「精确异常」要守住的东西。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>控制冒险是下一 PC 未知，不是操作数未知。</li><li>预测让 IF 继续；核对失败则冲刷，不得写回。</li><li>异常精确性是后课的缺口。</li><li>延迟槽不进入主干；当代核用预测加冲刷。</li><li>出处：Patterson and Hennessy, <em>COD</em> RISC-V；Hennessy and Patterson, <em>CA:AQA</em> 分支预测章。</li></ul>',7))])}const D=d(A,[["render",C]]);export{_ as __pageData,D as default};
